#!/bin/bash
# Runs INSIDE the jail: sources in /tmp/dir (read-only).
# Where the solution reads, writes and logs. A batch run uses MOJ's files; rbx's
# interactive driver runs this very script, unchanged, with these pointed at the
# interactor's pipes. stdout is opened before stdin below: on those pipes (FIFOs)
# the opening order is what pairs the solution up with the interactor.
RBX_STDIN="${RBX_STDIN:-/tmp/in}"
RBX_STDOUT="${RBX_STDOUT:-/tmp/out}"
RBX_STDERR="${RBX_STDERR:-/tmp/stderrlog}"
exec &>"$RBX_STDERR"
cd /tmp/dir
# binfile.sh is generated by build-and-test.sh and is the only channel carrying the
# problem's limits into the jail. It defines BIN, MOJ_MEMLIMITMB and MOJ_STACKKB.
source binfile.sh

# Quote every expansion of BIN: it carries the name the CONTESTANT submitted, which the
# judge materializes verbatim -- `l(1).cpp`, the mark a browser sticks on a repeated
# download, is a real report. Unquoted it reaches the shell raw and kills the run.

command -v pypy3 >/dev/null 2>&1 && exec pypy3 ./"$BIN" >"$RBX_STDOUT" <"$RBX_STDIN"
exec python3 ./"$BIN" >"$RBX_STDOUT" <"$RBX_STDIN"
